import type { VNode, VNodeChild } from '../vnode'
import {
  ARRAY_ITERATE_KEY,
  TrackOpTypes,
  isReactive,
  reactive,
  toRaw,
  track,
} from '@vue/reactivity'
import { isArray, isObject, isString } from '@vue/shared'
import { warn } from '../warning'

/**
 * v-for string
 * @private
 */
export function renderList(
  source: string,
  renderItem: (value: string, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for number
 */
export function renderList(
  source: number,
  renderItem: (value: number, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for array
 */
export function renderList<T>(
  source: T[],
  renderItem: (value: T, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for iterable
 */
export function renderList<T>(
  source: Iterable<T>,
  renderItem: (value: T, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for object
 */
export function renderList<T>(
  source: T,
  renderItem: <K extends keyof T>(
    value: T[K],
    key: string,
    index: number,
  ) => VNodeChild,
): VNodeChild[]

/**
 * Actual implementation
 */
export function renderList(
  source: any,
  renderItem: (...args: any[]) => VNodeChild,
  cache?: any[],
  index?: number,
): VNodeChild[] {
  let ret: VNodeChild[]
  const cached = ((cache && cache[index!]) || []) as VNode[]
  const sourceIsArray = isArray(source)
  const sourceIsString = isString(source)

  if (sourceIsArray || sourceIsString) {
    let sourceIsReactiveArray = false
    if (sourceIsArray) {
      sourceIsReactiveArray = isReactive(source)
    }
    if (sourceIsReactiveArray) {
      const observed = source
      const rawSource = toRaw(observed)
      const iterateType = TrackOpTypes.ITERATE
      track(rawSource, iterateType, ARRAY_ITERATE_KEY)
      source = rawSource
    }
    const len = source.length
    ret = new Array(len)
    for (let i = 0; i < len; i++) {
      const previous = cached[i]
      let item = source[i]
      if (sourceIsReactiveArray) {
        if (isObject(item)) {
          item = reactive(item)
        }
      }
      const vnode = renderItem(item, i, undefined, previous)
      ret[i] = vnode
    }
  } else if (typeof source === 'number') {
    if (__DEV__ && !Number.isInteger(source)) {
      warn(`The v-for range expect an integer value but got ${source}.`)
    }
    const range = source
    ret = new Array(range)
    for (let i = 0; i < range; i++) {
      const value = i + 1
      const previous = cached[i]
      const vnode = renderItem(value, i, undefined, previous)
      ret[i] = vnode
    }
  } else if (isObject(source)) {
    const iterator = source[Symbol.iterator as any]
    if (typeof iterator === 'function') {
      ret = []
      const iteratorInstance = iterator.call(source)
      let next = iteratorInstance.next()
      let i = 0
      while (!next.done) {
        const item = next.value
        const previous = cached[i]
        const vnode = renderItem(item, i, undefined, previous)
        ret.push(vnode)
        i++
        next = iteratorInstance.next()
      }
    } else {
      const keys = Object.keys(source)
      const keyCount = keys.length
      ret = new Array(keyCount)
      for (let i = 0; i < keyCount; i++) {
        const key = keys[i]
        const value = source[key]
        const previous = cached[i]
        const vnode = renderItem(value, key, i, previous)
        ret[i] = vnode
      }
    }
  } else {
    ret = []
  }

  if (cache) {
    cache[index!] = ret
  }
  return ret
}

